mapper.select:
SELECT id, name AS title, employee_no AS number, employee_status AS status
FROM hr_employee
WHERE tenant_id = #{tenantId} AND deleted = 0
    AND (name LIKE #{pattern} ESCAPE '!' OR employee_no LIKE #{pattern} ESCAPE '!')


        AND user_id = #{scope.userId}

            AND dept_id IN #{departmentId}

        AND create_by = #{scope.creator}
        AND 1 = 2
